import { Controller, Get, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';
const CATEGORIES = ['지급', '공제'];
const USE_STATUSES = ['사용', '미사용'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 급여 사용 이력 테이블이 스키마에 없어 삭제 시 사용 여부는 확인하지 않는다 (todos 참조).

function text(v: unknown): string | null {
  return typeof v === 'string' && v.trim() !== '' ? v.trim() : null;
}

function invalid(status: number, code: string, message: string): ApiError {
  return new ApiError(status, code, message);
}

function pagingOf(q: Record<string, unknown>) {
  const rawPage = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
  const rawSize = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(q['size']);
  if (!Number.isInteger(rawPage) || rawPage < 0 || !Number.isInteger(rawSize) || rawSize < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
  }
  return { page: rawPage, size: Math.min(rawSize, MAX_SIZE) };
}

function idOf(v: string | undefined): string {
  if (!v || !/^\d+$/.test(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', 'ID 형식이 올바르지 않습니다.');
  }
  return v;
}

function numberOf(v: unknown, label: string, status: number, code: string): number | null {
  if (v === null || v === '') {
    return null;
  }
  const n = typeof v === 'number' ? v : typeof v === 'string' ? Number(v) : NaN;
  if (!Number.isFinite(n) || n < 0) {
    throw invalid(status, code, label + '은(는) 0 이상의 숫자여야 합니다.');
  }
  return n;
}

function isDateText(v: unknown): v is string {
  return typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v);
}

@Controller('api/v1')
export class FnSfr02006Controller {
  @Get('/pay-items')
  async listPayItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pagingOf(q);
    const params = {
      itemCategory: text(q['itemCategory']),
      useStatus: text(q['useStatus']),
    };
    const where =
      'WHERE (CAST(:itemCategory AS text) IS NULL OR item_category = CAST(:itemCategory AS text))' +
      ' AND (CAST(:useStatus AS text) IS NULL OR use_status = CAST(:useStatus AS text))';
    return transaction(async (db) => {
      const items = await db.query(
        'SELECT pay_item_id AS "payItemId", item_category AS "itemCategory", item_name AS "itemName",' +
          ' taxable_yn AS "taxableYn", use_status AS "useStatus"' +
          ' FROM pay_item ' + where +
          ' ORDER BY pay_item_id LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, size, offset: page * size },
      );
      const counts = await db.query('SELECT COUNT(*) AS "total" FROM pay_item ' + where, params);
      return { items, page, size, total: counts[0].total };
    });
  }

  @Post('/pay-items')
  @HttpCode(200)
  async createPayItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const itemCategory = text(data['itemCategory']);
    const itemName = text(data['itemName']);
    const useStatus = text(data['useStatus']);
    const taxableYn = data['taxableYn'] === undefined ? null : data['taxableYn'];
    if (
      !itemCategory || !CATEGORIES.includes(itemCategory) ||
      !itemName || itemName.length > 100 ||
      !useStatus || !USE_STATUSES.includes(useStatus) ||
      (taxableYn !== null && typeof taxableYn !== 'boolean')
    ) {
      throw invalid(422, 'PAY_ITEM_INVALID', '항목 구분, 항목명, 사용 여부를 올바르게 입력해 주세요.');
    }
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT pay_item_id FROM pay_item WHERE item_category = :itemCategory AND item_name = :itemName',
        { itemCategory, itemName },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'PAY_ITEM_DUPLICATED', '같은 구분과 항목명이 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO pay_item (item_category, item_name, taxable_yn, use_status, created_at, updated_at)' +
          ' VALUES (:itemCategory, :itemName, :taxableYn, :useStatus, now(), now())' +
          ' RETURNING pay_item_id AS "payItemId"',
        { itemCategory, itemName, taxableYn, useStatus },
      );
      return { payItemId: rows[0].payItemId };
    });
  }

  @Patch('/pay-items/:payItemId')
  async updatePayItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const payItemId = idOf(req.params['payItemId']);
    const data = checks.inputOf(req.body);
    let itemName: string | null = null;
    if (data['itemName'] !== undefined) {
      itemName = text(data['itemName']);
      if (!itemName || itemName.length > 100) {
        throw new ApiError(400, 'VALIDATION_FAILED', '항목명을 올바르게 입력해 주세요.');
      }
    }
    if (data['taxableYn'] !== undefined && data['taxableYn'] !== null && typeof data['taxableYn'] !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '과세 여부 형식이 올바르지 않습니다.');
    }
    let useStatus: string | null = null;
    if (data['useStatus'] !== undefined) {
      useStatus = text(data['useStatus']);
      if (!useStatus || !USE_STATUSES.includes(useStatus)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부 값이 올바르지 않습니다.');
      }
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT item_category AS "itemCategory", item_name AS "itemName", taxable_yn AS "taxableYn", use_status AS "useStatus"' +
          ' FROM pay_item WHERE pay_item_id = CAST(:payItemId AS bigint)',
        { payItemId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PAY_ITEM_NOT_FOUND', '지급공제항목을 찾을 수 없습니다.');
      }
      const cur = found[0];
      const nextName = itemName ?? cur.itemName;
      const nextTaxable = data['taxableYn'] === undefined ? cur.taxableYn : data['taxableYn'];
      const nextUse = useStatus ?? cur.useStatus;
      const dup = await db.query(
        'SELECT pay_item_id FROM pay_item WHERE item_category = :itemCategory AND item_name = :itemName' +
          ' AND pay_item_id <> CAST(:payItemId AS bigint)',
        { itemCategory: cur.itemCategory, itemName: nextName, payItemId },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'PAY_ITEM_DUPLICATED', '같은 구분과 항목명의 항목이 이미 있습니다.');
      }
      await db.execute(
        'UPDATE pay_item SET item_name = :itemName, taxable_yn = :taxableYn, use_status = :useStatus, updated_at = now()' +
          ' WHERE pay_item_id = CAST(:payItemId AS bigint)',
        { itemName: nextName, taxableYn: nextTaxable, useStatus: nextUse, payItemId },
      );
      return { payItemId: Number(payItemId) };
    });
  }

  @Delete('/pay-items/:payItemId')
  async deletePayItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const payItemId = idOf(req.params['payItemId']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT pay_item_id FROM pay_item WHERE pay_item_id = CAST(:payItemId AS bigint)',
        { payItemId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PAY_ITEM_NOT_FOUND', '지급공제항목을 찾을 수 없습니다.');
      }
      await db.execute('DELETE FROM pay_item WHERE pay_item_id = CAST(:payItemId AS bigint)', { payItemId });
      return {};
    });
  }

  @Get('/social-insurance-configs')
  async listSocialInsuranceConfigs(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pagingOf(q);
    const params = {
      insuranceType: text(q['insuranceType']),
      useStatus: text(q['useStatus']),
    };
    const where =
      'WHERE (CAST(:insuranceType AS text) IS NULL OR insurance_type = CAST(:insuranceType AS text))' +
      ' AND (CAST(:useStatus AS text) IS NULL OR use_status = CAST(:useStatus AS text))';
    return transaction(async (db) => {
      const items = await db.query(
        'SELECT social_insurance_config_id AS "socialInsuranceConfigId", insurance_type AS "insuranceType",' +
          ' rate AS "rate", base_amount_min AS "baseAmountMin", base_amount_max AS "baseAmountMax",' +
          ' to_char(effective_start_date, \'YYYY-MM-DD\') AS "effectiveStartDate", use_status AS "useStatus"' +
          ' FROM social_insurance_config ' + where +
          ' ORDER BY insurance_type, effective_start_date DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, size, offset: page * size },
      );
      const counts = await db.query('SELECT COUNT(*) AS "total" FROM social_insurance_config ' + where, params);
      return { items, page, size, total: counts[0].total };
    });
  }

  @Post('/social-insurance-configs')
  @HttpCode(200)
  async createSocialInsuranceConfig(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const code = 'SOCIAL_INSURANCE_CONFIG_INVALID';
    const insuranceType = text(data['insuranceType']);
    const useStatus = text(data['useStatus']);
    const effectiveStartDate = data['effectiveStartDate'];
    if (
      !insuranceType || insuranceType.length > 50 ||
      !useStatus || !USE_STATUSES.includes(useStatus) ||
      !isDateText(effectiveStartDate)
    ) {
      throw invalid(422, code, '사회보험 종류, 적용 시작일, 사용 여부를 올바르게 입력해 주세요.');
    }
    const rate = numberOf(data['rate'] ?? null, '요율', 422, code);
    const baseAmountMin = numberOf(data['baseAmountMin'] ?? null, '기준 하한금액', 422, code);
    const baseAmountMax = numberOf(data['baseAmountMax'] ?? null, '기준 상한금액', 422, code);
    if (baseAmountMin !== null && baseAmountMax !== null && baseAmountMax < baseAmountMin) {
      throw invalid(422, code, '기준 상한금액은 하한금액 이상이어야 합니다.');
    }
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT social_insurance_config_id FROM social_insurance_config' +
          ' WHERE insurance_type = :insuranceType AND effective_start_date = CAST(:effectiveStartDate AS date)',
        { insuranceType, effectiveStartDate },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'SOCIAL_INSURANCE_CONFIG_DUPLICATED', '같은 종류와 적용 시작일의 환경이 이미 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO social_insurance_config (insurance_type, rate, base_amount_min, base_amount_max,' +
          ' effective_start_date, use_status, created_at, updated_at)' +
          ' VALUES (:insuranceType, CAST(:rate AS numeric), CAST(:baseAmountMin AS numeric), CAST(:baseAmountMax AS numeric),' +
          ' CAST(:effectiveStartDate AS date), :useStatus, now(), now())' +
          ' RETURNING social_insurance_config_id AS "socialInsuranceConfigId"',
        { insuranceType, rate, baseAmountMin, baseAmountMax, effectiveStartDate, useStatus },
      );
      return { socialInsuranceConfigId: rows[0].socialInsuranceConfigId };
    });
  }

  @Patch('/social-insurance-configs/:socialInsuranceConfigId')
  async updateSocialInsuranceConfig(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const configId = idOf(req.params['socialInsuranceConfigId']);
    const data = checks.inputOf(req.body);
    const code = 'VALIDATION_FAILED';
    if (data['effectiveStartDate'] !== undefined && !isDateText(data['effectiveStartDate'])) {
      throw invalid(400, code, '적용 시작일 형식이 올바르지 않습니다.');
    }
    let useStatus: string | null = null;
    if (data['useStatus'] !== undefined) {
      useStatus = text(data['useStatus']);
      if (!useStatus || !USE_STATUSES.includes(useStatus)) {
        throw invalid(400, code, '사용 여부 값이 올바르지 않습니다.');
      }
    }
    const rateIn = data['rate'] === undefined ? undefined : numberOf(data['rate'], '요율', 400, code);
    const minIn = data['baseAmountMin'] === undefined ? undefined : numberOf(data['baseAmountMin'], '기준 하한금액', 400, code);
    const maxIn = data['baseAmountMax'] === undefined ? undefined : numberOf(data['baseAmountMax'], '기준 상한금액', 400, code);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT insurance_type AS "insuranceType", rate AS "rate", base_amount_min AS "baseAmountMin",' +
          ' base_amount_max AS "baseAmountMax", to_char(effective_start_date, \'YYYY-MM-DD\') AS "effectiveStartDate",' +
          ' use_status AS "useStatus"' +
          ' FROM social_insurance_config WHERE social_insurance_config_id = CAST(:configId AS bigint)',
        { configId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'SOCIAL_INSURANCE_CONFIG_NOT_FOUND', '사회보험 환경 설정을 찾을 수 없습니다.');
      }
      const cur = found[0];
      const rate = rateIn === undefined ? cur.rate : rateIn;
      const baseAmountMin = minIn === undefined ? cur.baseAmountMin : minIn;
      const baseAmountMax = maxIn === undefined ? cur.baseAmountMax : maxIn;
      const effectiveStartDate = data['effectiveStartDate'] === undefined ? cur.effectiveStartDate : data['effectiveStartDate'];
      const nextUse = useStatus ?? cur.useStatus;
      if (baseAmountMin !== null && baseAmountMax !== null && Number(baseAmountMax) < Number(baseAmountMin)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '기준 상한금액은 하한금액 이상이어야 합니다.');
      }
      const dup = await db.query(
        'SELECT social_insurance_config_id FROM social_insurance_config' +
          ' WHERE insurance_type = :insuranceType AND effective_start_date = CAST(:effectiveStartDate AS date)' +
          ' AND social_insurance_config_id <> CAST(:configId AS bigint)',
        { insuranceType: cur.insuranceType, effectiveStartDate, configId },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'SOCIAL_INSURANCE_CONFIG_DUPLICATED', '같은 종류와 적용 시작일의 환경이 이미 있습니다.');
      }
      await db.execute(
        'UPDATE social_insurance_config SET rate = CAST(:rate AS numeric), base_amount_min = CAST(:baseAmountMin AS numeric),' +
          ' base_amount_max = CAST(:baseAmountMax AS numeric), effective_start_date = CAST(:effectiveStartDate AS date),' +
          ' use_status = :useStatus, updated_at = now()' +
          ' WHERE social_insurance_config_id = CAST(:configId AS bigint)',
        { rate, baseAmountMin, baseAmountMax, effectiveStartDate, useStatus: nextUse, configId },
      );
      return { socialInsuranceConfigId: Number(configId) };
    });
  }
}

