import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  Num,
  NumberInput,
  Pager,
  Select,
  Tiles,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const SIZE = 10;
const USE_OPTIONS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];
const CATEGORY_OPTIONS: [string, string][] = [['지급', '지급'], ['공제', '공제']];
const TAX_OPTIONS: [string, string][] = [['true', '과세'], ['false', '비과세']];

function taxText(v: unknown): string {
  return v === true ? '과세' : v === false ? '비과세' : '-';
}

function PayItemDrawer({ role, row, onClose, onDone, notify }: {
  role: string;
  row: Row | null;
  onClose: () => void;
  onDone: () => void;
  notify: (text: string) => void;
}) {
  const editing = row !== null;
  const [itemCategory, setItemCategory] = useState(editing ? String(row.itemCategory) : '');
  const [itemName, setItemName] = useState(editing ? String(row.itemName) : '');
  const [taxable, setTaxable] = useState(editing && typeof row.taxableYn === 'boolean' ? String(row.taxableYn) : '');
  const [useStatus, setUseStatus] = useState(editing ? String(row.useStatus) : '사용');

  async function save() {
    if (!itemCategory || !itemName.trim() || !useStatus) {
      throw new Error('항목 구분, 항목명, 사용 여부를 입력해 주세요.');
    }
    const body: Row = { itemName: itemName.trim(), useStatus };
    if (taxable !== '') {
      body.taxableYn = taxable === 'true';
    }
    if (editing) {
      await call('PATCH', '/pay-items/' + row.payItemId, role, body);
      notify('지급공제항목을 수정했습니다.');
    } else {
      body.itemCategory = itemCategory;
      await call('POST', '/pay-items', role, body);
      notify('지급공제항목을 등록했습니다.');
    }
    onDone();
  }

  async function remove() {
    await call('DELETE', '/pay-items/' + row?.payItemId, role);
    notify('지급공제항목을 삭제했습니다.');
    onDone();
  }

  return (
    <Drawer title={editing ? '지급공제항목 수정' : '지급공제항목 등록'} onClose={onClose}>
      <Form onSubmit={save} submit={editing ? '수정' : '등록'}>
        <Field label="항목 구분" required>
          {editing ? <Badge value={itemCategory} /> : <Select value={itemCategory} onChange={setItemCategory} options={CATEGORY_OPTIONS} />}
        </Field>
        <Field label="항목명" required>
          <TextInput value={itemName} onChange={setItemName} />
        </Field>
        <Field label="과세 여부">
          <Select value={taxable} onChange={setTaxable} options={TAX_OPTIONS} placeholder="선택 안 함" />
        </Field>
        <Field label="사용 여부" required>
          <Select value={useStatus} onChange={setUseStatus} options={USE_OPTIONS} />
        </Field>
      </Form>
      {editing && (
        <Form
          danger
          submit="삭제"
          onSubmit={remove}
          note="급여에 사용된 항목은 삭제할 수 없고 미사용 처리만 가능합니다."
        />
      )}
    </Drawer>
  );
}

function InsuranceDrawer({ role, row, onClose, onDone, notify }: {
  role: string;
  row: Row | null;
  onClose: () => void;
  onDone: () => void;
  notify: (text: string) => void;
}) {
  const editing = row !== null;
  const [insuranceType, setInsuranceType] = useState(editing ? String(row.insuranceType) : '');
  const [rate, setRate] = useState<number | string>(editing ? (row.rate as number | null) ?? '' : '');
  const [baseAmountMin, setMin] = useState<number | string>(editing ? (row.baseAmountMin as number | null) ?? '' : '');
  const [baseAmountMax, setMax] = useState<number | string>(editing ? (row.baseAmountMax as number | null) ?? '' : '');
  const [effectiveStartDate, setDate] = useState(editing ? String(row.effectiveStartDate) : '');
  const [useStatus, setUseStatus] = useState(editing ? String(row.useStatus) : '사용');

  async function save() {
    if (!insuranceType.trim() || !effectiveStartDate || !useStatus) {
      throw new Error('사회보험 종류, 적용 시작일, 사용 여부를 입력해 주세요.');
    }
    const body: Row = { rate, baseAmountMin, baseAmountMax, effectiveStartDate, useStatus };
    if (editing) {
      await call('PATCH', '/social-insurance-configs/' + row.socialInsuranceConfigId, role, body);
      notify('사회보험 환경을 수정했습니다.');
    } else {
      body.insuranceType = insuranceType.trim();
      await call('POST', '/social-insurance-configs', role, body);
      notify('사회보험 환경을 등록했습니다.');
    }
    onDone();
  }

  return (
    <Drawer title={editing ? '사회보험 환경 수정' : '사회보험 환경 등록'} onClose={onClose}>
      <Form onSubmit={save} submit={editing ? '수정' : '등록'}>
        <Field label="사회보험 종류" required>
          {editing ? <span>{insuranceType}</span> : <TextInput value={insuranceType} onChange={setInsuranceType} />}
        </Field>
        <Field label="요율">
          <NumberInput value={rate} onChange={setRate} />
        </Field>
        <Field label="기준 하한금액">
          <NumberInput value={baseAmountMin} onChange={setMin} />
        </Field>
        <Field label="기준 상한금액">
          <NumberInput value={baseAmountMax} onChange={setMax} />
        </Field>
        <Field label="적용 시작일" required>
          <DateInput value={effectiveStartDate} onChange={setDate} />
        </Field>
        <Field label="사용 여부" required>
          <Select value={useStatus} onChange={setUseStatus} options={USE_OPTIONS} />
        </Field>
      </Form>
    </Drawer>
  );
}

export default function FnSfr02006Page({ role, notify }: PageProps) {
  const [payDraft, setPayDraft] = useState({ itemCategory: '', useStatus: '' });
  const [payQuery, setPayQuery] = useState({ itemCategory: '', useStatus: '' });
  const [payPage, setPayPage] = useState(0);
  const [payDrawer, setPayDrawer] = useState<{ row: Row | null } | null>(null);

  const [insDraft, setInsDraft] = useState({ insuranceType: '', useStatus: '' });
  const [insQuery, setInsQuery] = useState({ insuranceType: '', useStatus: '' });
  const [insPage, setInsPage] = useState(0);
  const [insDrawer, setInsDrawer] = useState<{ row: Row | null } | null>(null);

  const pay = useData(
    () => call<Page>('GET', '/pay-items', role, undefined, { ...payQuery, page: payPage, size: SIZE }),
    [payQuery, payPage],
  );
  const ins = useData(
    () => call<Page>('GET', '/social-insurance-configs', role, undefined, { ...insQuery, page: insPage, size: SIZE }),
    [insQuery, insPage],
  );

  const payColumns: Column[] = [
    { key: 'itemCategory', label: '항목 구분', render: (r) => <Badge value={r.itemCategory} /> },
    { key: 'itemName', label: '항목명' },
    { key: 'taxableYn', label: '과세 여부', render: (r) => <span>{taxText(r.taxableYn)}</span> },
    { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r.useStatus} /> },
  ];
  const insColumns: Column[] = [
    { key: 'insuranceType', label: '사회보험 종류' },
    { key: 'rate', label: '요율', render: (r) => <Num value={r.rate} /> },
    { key: 'baseAmountMin', label: '기준 하한금액', render: (r) => <Num value={r.baseAmountMin} /> },
    { key: 'baseAmountMax', label: '기준 상한금액', render: (r) => <Num value={r.baseAmountMax} /> },
    { key: 'effectiveStartDate', label: '적용 시작일', render: (r) => <DateText value={r.effectiveStartDate} /> },
    { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r.useStatus} /> },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현황</h2>
        <Tiles
          items={[
            ['지급공제항목', <Num value={pay.data?.total ?? 0} />],
            ['사회보험 환경', <Num value={ins.data?.total ?? 0} />],
          ]}
        />
      </section>

      <section className="box span-12">
        <h2>지급공제항목</h2>
        <Filters
          onSearch={() => {
            setPayPage(0);
            setPayQuery(payDraft);
          }}
          onReset={() => {
            const empty = { itemCategory: '', useStatus: '' };
            setPayDraft(empty);
            setPayPage(0);
            setPayQuery(empty);
          }}
        >
          <Field label="항목 구분">
            <Select value={payDraft.itemCategory} onChange={(v) => setPayDraft({ ...payDraft, itemCategory: v })} options={CATEGORY_OPTIONS} placeholder="전체" />
          </Field>
          <Field label="사용 여부">
            <Select value={payDraft.useStatus} onChange={(v) => setPayDraft({ ...payDraft, useStatus: v })} options={USE_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={pay.data?.total}>
          <button type="button" onClick={() => setPayDrawer({ row: null })}>항목 등록</button>
        </Band>
        {pay.error && <ErrorText text={pay.error} />}
        <DataTable columns={payColumns} rows={pay.data?.items ?? []} onRowClick={(r) => setPayDrawer({ row: r })} empty="등록된 항목이 없습니다." />
        <Pager page={payPage} size={SIZE} total={pay.data?.total ?? 0} onPage={setPayPage} />
      </section>

      <section className="box span-12">
        <h2>사회보험 환경</h2>
        <Filters
          onSearch={() => {
            setInsPage(0);
            setInsQuery(insDraft);
          }}
          onReset={() => {
            const empty = { insuranceType: '', useStatus: '' };
            setInsDraft(empty);
            setInsPage(0);
            setInsQuery(empty);
          }}
        >
          <Field label="사회보험 종류">
            <TextInput value={insDraft.insuranceType} onChange={(v) => setInsDraft({ ...insDraft, insuranceType: v })} />
          </Field>
          <Field label="사용 여부">
            <Select value={insDraft.useStatus} onChange={(v) => setInsDraft({ ...insDraft, useStatus: v })} options={USE_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={ins.data?.total}>
          <button type="button" onClick={() => setInsDrawer({ row: null })}>환경 등록</button>
        </Band>
        {ins.error && <ErrorText text={ins.error} />}
        <DataTable columns={insColumns} rows={ins.data?.items ?? []} onRowClick={(r) => setInsDrawer({ row: r })} empty="등록된 환경이 없습니다." />
        <Pager page={insPage} size={SIZE} total={ins.data?.total ?? 0} onPage={setInsPage} />
      </section>

      {payDrawer && (
        <PayItemDrawer
          role={role}
          row={payDrawer.row}
          notify={notify}
          onClose={() => setPayDrawer(null)}
          onDone={() => {
            setPayDrawer(null);
            pay.reload();
          }}
        />
      )}
      {insDrawer && (
        <InsuranceDrawer
          role={role}
          row={insDrawer.row}
          notify={notify}
          onClose={() => setInsDrawer(null)}
          onDone={() => {
            setInsDrawer(null);
            ins.reload();
          }}
        />
      )}
    </div>
  );
}
